function evenStepsPossible(arr: number[]): boolean {
  const a = [...arr].sort((x, y) => x - y);
  const d = a[1] - a[0];
  for (let i = 2; i < a.length; i++) {
    if (a[i] - a[i - 1] !== d) return false;
  }
  return true;
}

