function evenStepsPossible(arr: number[]): boolean {
  const n = arr.length;
  const lo = arr.reduce((m, x) => Math.min(m, x)), hi = arr.reduce((m, x) => Math.max(m, x));
  if ((hi - lo) % (n - 1) !== 0) return false;
  const d = (hi - lo) / (n - 1);
  if (d === 0) return true; // min equals max, so all values are equal
  const used = new Uint8Array(n);
  for (const x of arr) {
    if ((x - lo) % d !== 0) return false;
    const slot = (x - lo) / d;
    if (used[slot]) return false;
    used[slot] = 1;
  }
  return true;
}

