        n = len(arr)
        lo, hi = min(arr), max(arr)
        if (hi - lo) % (n - 1):
            return False
        d = (hi - lo) // (n - 1)
        if d == 0:
            return True  # min equals max, so all values are equal
        used = [False] * n
        for x in arr:
            if (x - lo) % d:
                return False
            slot = (x - lo) // d
            if used[slot]:
                return False
            used[slot] = True
        return True

